// 기본 검색어(비율 계산용)와 맞벌이 신호 검색어(사례 수집용)를 구분해서 요청 목록을 만든다
const cfg = $input.first().json;
const split = (v) => String(v || '').split(',').map(s => s.trim()).filter(Boolean);
const groups = [['기본', split(cfg.baseQueries)], ['맞벌이신호', split(cfg.signalQueries)]];
const sorts = ['sim', 'date'];          // 정확도순 + 최신순 (둘 다 받아서 중복 제거)
const out = [];
for (const [group, qs] of groups) {
  for (const q of qs) {
    for (const s of sorts) {
      for (let start = 1; start <= 901; start += 100) {   // 네이버 API는 start 최대 1000
        out.push({ json: { query: q, group, sort: s, start } });
      }
    }
  }
}
return out;

const reqs = $('요청목록 생성').all();
const clean = (s) => String(s || '')
  .replace(/<[^>]*>/g, '')
  .replace(/&quot;/g, '"').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/&apos;|&#39;/g, "'").replace(/\s+/g, ' ').trim();

// 카페 유형 (기존 6,247건 수집과 같은 규칙, 업체 카페는 따로 표시)
const cafeRules = [
  ['업체·영업',     /설치|세척|청소업|수리|렌탈|이전설치|시공|매입|창업/],
  ['육아·맘카페',   /맘|육아|아기|베이비|키즈|아가|엄마|임신|출산/],
  ['신혼·결혼',     /신혼|결혼|웨딩|예비부부|혼수/],
  ['입주·인테리어', /인테리어|입주|아파트|이사|부동산|리모델링|하우스/],
  ['지역·생활',     /맛집|동네|지역|시$|구$|군$|생활|주부|살림/],
];
const postRules = [
  ['고장·AS',     /고장|수리|AS|as|A\/S|에러|오류|안\s?나|안\s?켜|안\s?돼|안\s?되|누수|물\s?샘|물이|소음|냄새|이상|결로|얼음|꺼져|꺼짐|불량|서비스센터|기사님|출장/],
  ['설치·이전',   /설치|이전|철거|배관|타공|브라켓|재설치/],
  ['구매고민',    /추천|비교|가격|뭐가|살까|구매|구입|견적|할인|특가|최저가|vs|VS|신제품/],
  ['청소·관리',   /청소|필터|세척|관리|곰팡이/],
];
const pick = (rules, text, fallback) => { for (const [n, re] of rules) if (re.test(text)) return n; return fallback; };

// 맞벌이 신호어 (제목+요약에서 찾음)
const SIGNALS = ['맞벌이','워킹맘','직장맘','출근','퇴근','회사','직장','근무','반차','연차','휴가','평일','낮에','어린이집','등원','하원','등하원','돌봄','야근','출장 중','시터','이모님'];
// 막힌 점
const blockRules = [
  ['연락·연결', /연락|전화|통화|연결|상담원|콜센터|고객센터|답이 없|안 받/],
  ['방문 일정', /방문|일정|예약|시간|주말|토요일|저녁|날짜|오전|오후|기사님?\s?(오|와)/],
  ['대기',      /대기|기다|밀려|일주일|며칠|2주|열흘|한참/],
  ['비용',      /비용|출장비|수리비|유상|무상|돈|만원/],
];
const brand = (t) => /LG|엘지|휘센|whisen|WHISEN/i.test(t) ? 'LG' : (/삼성|무풍|캐리어|위니아|대우|신일|파세코|센추리/.test(t) ? '타사' : '불명');

const seen = new Set();
const rows = [];
for (const it of $input.all()) {
  const items = it.json && it.json.items;
  if (!Array.isArray(items)) continue;      // 오류 응답은 건너뜀
  const idx = it.pairedItem && it.pairedItem.item;
  const req = (reqs[idx] && reqs[idx].json) || {};
  for (const p of items) {
    const link = p.link || '';
    if (!link || seen.has(link)) continue;
    seen.add(link);
    const cafe = clean(p.cafename);
    const title = clean(p.title);
    const desc = clean(p.description);
    const text = title + ' ' + desc;
    const sig = SIGNALS.filter(w => text.includes(w));
    const blocks = blockRules.filter(([, re]) => re.test(text)).map(([n]) => n);
    rows.push({ json: {
      카페명: cafe,
      카페주소: p.cafeurl || '',
      카페유형: pick(cafeRules, cafe, '기타·미분류'),
      글성격: pick(postRules, text, '기타'),
      브랜드: brand(text),
      맞벌이신호: sig.length ? 'Y' : 'N',
      신호어: sig.join(' '),
      막힌점: blocks.join(' '),
      제목: title,
      요약: desc,
      링크: link,
      검색어: req.query || '',
      검색어그룹: req.group || '',
    }});
  }
}
if (!rows.length) throw new Error('수집된 글이 없습니다. 설정 노드의 Client ID/Secret과 검색 API 권한(검색)을 확인하세요.');
return rows;

// 비율은 '기본' 검색어로 모은 글로만 계산한다 (맞벌이 검색어로 모은 글을 넣으면 비율이 부풀려짐)
const all = $input.all().map(i => i.json);
const out = [];
const add = (구분, 항목, 건수, 분모, 비고 = '') =>
  out.push({ json: { 구분, 항목, 건수, '비율(%)': 분모 ? Math.round(건수 / 분모 * 1000) / 10 : '', 분모: 분모 || '', 비고 } });
const cnt = (rows, f) => rows.filter(f).length;

const base = all.filter(r => r.검색어그룹 === '기본');
add('전체', '수집 글(중복 제거)', all.length, 0, '기본+맞벌이신호 검색어');
add('전체', '기본 검색어 글', base.length, 0);
for (const [label, rows] of [['기본 · 전체 브랜드', base], ['기본 · LG만', base.filter(r => r.브랜드 === 'LG')]]) {
  const mom = rows.filter(r => r.카페유형 === '육아·맘카페');
  const momAS = mom.filter(r => r.글성격 === '고장·AS');
  const momASsig = momAS.filter(r => r.맞벌이신호 === 'Y');
  const restAS = rows.filter(r => r.카페유형 !== '육아·맘카페' && r.카페유형 !== '업체·영업' && r.글성격 === '고장·AS');
  add(label, '맘카페 글', mom.length, rows.length, '전체 글 중');
  add(label, '맘카페 고장·AS 글', momAS.length, mom.length, '맘카페 글 중');
  add(label, '★ 맘카페 고장·AS 중 맞벌이 신호', momASsig.length, momAS.length, '맘카페 고장·AS 글 중');
  add(label, '비교: 다른 고객 카페 고장·AS 중 맞벌이 신호', cnt(restAS, r => r.맞벌이신호 === 'Y'), restAS.length, '업체·맘카페 제외');
  for (const b of ['연락·연결', '방문 일정', '대기', '비용'])
    add(label, '맞벌이 신호 글의 막힌 점: ' + b, cnt(momASsig, r => r.막힌점.includes(b)), momASsig.length, '중복 가능');
}
// 신호어별 (맘카페 고장·AS, 전체 그룹)
const momASall = all.filter(r => r.카페유형 === '육아·맘카페' && r.글성격 === '고장·AS');
const wc = new Map();
for (const r of momASall) for (const w of r.신호어.split(' ').filter(Boolean)) wc.set(w, (wc.get(w) || 0) + 1);
for (const [w, n] of [...wc.entries()].sort((a, b) => b[1] - a[1])) add('신호어(맘카페 고장·AS, 전체 검색어)', w, n, momASall.length);
// 검색어별 수집량
const qc = new Map();
for (const r of all) qc.set(r.검색어그룹 + ' | ' + r.검색어, (qc.get(r.검색어그룹 + ' | ' + r.검색어) || 0) + 1);
for (const [q, n] of qc) add('검색어별 수집', q, n, all.length);
return out;

// 사람이 읽고 확인할 후보: 맘카페 · 고장·AS · 맞벌이 신호 있음
return $input.all().filter(i => i.json.카페유형 === '육아·맘카페' && i.json.글성격 === '고장·AS' && i.json.맞벌이신호 === 'Y')
  .map(i => ({ json: { ...i.json, '사람확인(맞벌이 맞음 Y/N)': '' } }));
